37	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
38	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
39	// intermediates to stay exact, so every percentage goes through here.
40	const percentOf = (amount: number, percent: number): number =>
41	  (amount * percent) / 100;
42	
43	const quoteStep = (step: Step): QuoteResult => {
44	  const basePremium = step.items.reduce(
45	    (sum, item) => sum + BASE_PREMIUMS[item.type],
46	    0,
47	  );
48	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
49	
50	  return {
51	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
52	  };
53	};
